+/**
+ * Decimal backed money helpers.
+ *
+ * Amounts cross module boundaries as plain numbers and are converted to
+ * Decimal only for the arithmetic that has to stay exact.
+ */
+
+import Decimal from 'decimal.js';
+
+export const MONEY_DECIMAL_PLACES = 2;
+
+export function toDecimal(value: number, label = 'Amount'): Decimal {
+  if (!Number.isFinite(value)) {
+    throw new RangeError(`${label} must be a finite number, received ${value}`);
+  }
+  return new Decimal(value);
+}
+
+/**
+ * Rounds to two decimal places, half away from zero.
+ */
+export function roundMoney(value: Decimal): number {
+  return value.toDecimalPlaces(MONEY_DECIMAL_PLACES, Decimal.ROUND_HALF_UP).toNumber();
+}
+
+export function addMoney(left: number, right: number): Decimal {
+  return toDecimal(left).plus(toDecimal(right));
+}
+
+export function subtractMoney(left: number, right: number): Decimal {
+  return toDecimal(left).minus(toDecimal(right));
+}
+
+export function multiplyMoney(value: number, factor: number): Decimal {
+  return toDecimal(value).times(toDecimal(factor, 'Factor'));
+}
+
+/**
+ * Returns the part of an amount described by a percentage.
+ */
+export function percentOf(value: Decimal, percent: Decimal): Decimal {
+  return value.times(percent).dividedBy(100);
+}
+
+/**
+ * Keeps a discounted amount from falling below zero.
+ */
+export function clampToZero(value: Decimal): Decimal {
+  return value.isNegative() ? new Decimal(0) : value;
+}
+
+export function sumMoney(values: readonly Decimal[]): Decimal {
+  return values.reduce((total, value) => total.plus(value), new Decimal(0));
+}"},{"filename":"test/pricing/discount.test.ts","status":"modified","additions":12,"deletions":18,"changes":30,"patch":"@@ -1,18 +1,12 @@
